export function researchCopy(locale: Locale): ResearchCopy {
  return { ...copy.en, ...copy[locale] } as ResearchCopy
}

export function dateLocale(locale: Locale) {
  return locale === 'zh-TW' ? 'zh-TW' : locale === 'zh-CN' ? 'zh-CN' : 'en-US'
}

export function statusLabel(value: string, c: ResearchCopy) {
  const map: Record<string, keyof ResearchCopy> = {
    FULL: 'full', LIMITED: 'limited', STALE: 'stale', FAILED: 'failedStatus',
    DRAFT: 'draft', CHANGES_REQUIRED: 'changesRequired', APPROVED: 'approved',
    CREATED: 'created', COLLECTING: 'collecting', DATA_READY: 'dataReady', GENERATING: 'generatingStatus', DRAFT_READY: 'draftReady', BLOCKED: 'blockedStatus', CANCELLED: 'cancelled',
    NOT_SENT: 'notSent', DISPATCH_INTENT: 'dispatchIntent', SENT: 'sent', SUCCEEDED: 'succeeded', OUTCOME_UNKNOWN: 'unknownOutcome',
    PASS: 'pass', WARN: 'warn', FAIL: 'fail', NOT_CHECKED: 'notChecked', N_A: 'notApplicable',
  }
  const key = map[value]
  return key ? c[key] : value
}

export function formatDate(value: string | null | undefined, locale: Locale, withTime = false) {
  if (!value) return '—'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return new Intl.DateTimeFormat(dateLocale(locale), withTime ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }).format(date)
}

export function randomIdempotencyKey() {
  return `research-${crypto.randomUUID()}`
}

