export function researchConfigurationCopy(locale: Locale) {
  return configurationCopy[locale]
}

export type ResearchConfigurationCopy = ReturnType<typeof researchConfigurationCopy>

export const researchSourcePurposeKeys = [
  'automatedFetch',
  'evidenceStorage',
  'llmInference',
  'publicationOfAnalysisAndExcerpts',
  'rawDataRedistribution',
] as const

export function permissionStatusLabel(status: string, c: ResearchConfigurationCopy) {
  if (status === 'allowed') return c.allowed
  if (status === 'restricted') return c.restricted
  return c.unknownPermission
}
